files.content:
.diagram{
  margin:0;
  display:flex;
  flex-direction:column;
  gap:var(--s-5);
  padding:var(--s-6);
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
}
.diagram-canvas{
  display:flex;
  justify-content:center;
  align-items:center;
  min-height:140px;
  padding:var(--s-4) var(--s-2);
  overflow-x:auto;
}
.diagram-canvas svg{
  max-width:100%;
  height:auto;
  display:block;
}
.diagram-canvas foreignObject{
  overflow:visible;
}
.diagram-caption{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-400);
}
.diagram-caption .num{
  color:var(--primary-400);
}
.diagram-legend{
  display:flex;
  flex-wrap:wrap;
  gap:var(--s-3) var(--s-5);
  padding-top:var(--s-4);
  border-top:var(--bw-1) solid var(--obsidian-800);
}
.diagram-legend-item{
  display:flex;
  align-items:center;
  gap:var(--s-2);
  font-size:var(--t-small);
  color:var(--obsidian-200);
}
.diagram-legend-swatch{
  width:20px;
  height:20px;
  flex-shrink:0;
  background:var(--obsidian-800);
  border:var(--bw-1) solid var(--obsidian-600);
}
.diagram-legend-meta{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-400);
}
@media (max-width: 720px){
  .diagram{
    padding:var(--s-5);
  }
  .diagram-canvas{
    padding:var(--s-2) 0;
  }
}
